DEFAULT_CATEGORIES = [
    ("Políticas", "Reglas y lineamientos de la empresa."),
    ("Procedimientos", "Cómo se hacen las cosas, paso a paso."),
    ("Manuales y guías", "Instructivos de sistemas, equipos y procesos."),
    ("Formatos y plantillas", "Archivos para llenar o reutilizar."),
    ("Comunicados", "Avisos oficiales y circulares."),
    ("Otros", "Lo que no entra en otra categoría."),
]


def create_categories(apps, schema_editor):
    DocumentCategory = apps.get_model("documents", "DocumentCategory")
    for position, (name, description) in enumerate(DEFAULT_CATEGORIES, start=1):
        DocumentCategory.objects.get_or_create(name=name, defaults={"description": description, "position": position})


